package com.edunest.backend.modules.syllabus.service.impl;
import com.edunest.backend.common.exception.ResourceNotFoundException; import com.edunest.backend.common.util.PublicIdUtils; import com.edunest.backend.modules.subject.entity.Subject; import com.edunest.backend.modules.subject.dto.SubjectResponseDto; import com.edunest.backend.modules.subject.repository.SubjectRepository; import com.edunest.backend.modules.syllabus.dto.*; import com.edunest.backend.modules.syllabus.service.SyllabusService; import com.edunest.backend.modules.topic.entity.Topic; import com.edunest.backend.modules.topic.dto.TopicResponse; import com.edunest.backend.modules.topic.repository.TopicRepository; import com.edunest.backend.modules.unit.entity.Unit; import com.edunest.backend.modules.unit.repository.UnitRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class SyllabusServiceImpl implements SyllabusService { private final SubjectRepository subjects; private final UnitRepository units; private final TopicRepository topics;
@Override @Transactional(readOnly=true) public SyllabusResponse getSubjectSyllabus(Long id){ Subject s=subjects.findById(id).filter(Subject::isActive).orElseThrow(()->new ResourceNotFoundException("Subject not found")); List<Unit> us=units.findBySubjectIdAndActiveTrueOrderByUnitNumberAsc(id); List<Long> ids=us.stream().map(Unit::getId).toList(); Map<Long,List<Topic>> map=ids.isEmpty()?Map.of():topics.findByUnit_IdInAndActiveTrueOrderByUnit_IdAscTopicNumberAsc(ids).stream().collect(Collectors.groupingBy(t->t.getUnit().getId())); List<SyllabusUnitResponse> out=us.stream().map(u->SyllabusUnitResponse.builder().id(PublicIdUtils.unitId(u.getId())).unitNumber(u.getUnitNumber()).chapterName(u.getChapterName()).description(u.getDescription()).topics(map.getOrDefault(u.getId(),List.of()).stream().map(this::topic).toList()).build()).toList(); return SyllabusResponse.builder().subject(subject(s)).units(out).build();}
private SubjectResponseDto subject(Subject s){return SubjectResponseDto.builder().id(PublicIdUtils.subjectId(s.getId())).name(s.getName()).code(s.getCode()).active(s.isActive()).subjectCategory(s.getSubjectCategory()).examType(s.getExamType()).lectureHours(s.getLectureHours()).tutorialHours(s.getTutorialHours()).practicalHours(s.getPracticalHours()).inSemMarks(s.getInSemMarks()).endSemMarks(s.getEndSemMarks()).practicalMarks(s.getPracticalMarks()).oralMarks(s.getOralMarks()).termWorkMarks(s.getTermWorkMarks()).credits(s.getCredits()).elective(s.isElective()).electiveGroup(s.getElectiveGroup()).honors(s.isHonors()).minor(s.isMinor()).branchId(PublicIdUtils.branchId(s.getBranch().getId())).branchName(s.getBranch().getName()).semesterId(PublicIdUtils.semesterId(s.getSemester().getId())).semesterName(s.getSemester().getName()).academicYearId(PublicIdUtils.academicYearId(s.getAcademicYear().getId())).academicYearName(s.getAcademicYear().getName()).build();}
private TopicResponse topic(Topic t){return TopicResponse.builder().id(PublicIdUtils.topicId(t.getId())).topicNumber(t.getTopicNumber()).name(t.getName()).description(t.getDescription()).active(t.isActive()).unitId(PublicIdUtils.unitId(t.getUnit().getId())).unitNumber(t.getUnit().getUnitNumber()).subjectId(PublicIdUtils.subjectId(t.getUnit().getSubject().getId())).subjectName(t.getUnit().getSubject().getName()).build();}
}